import{z as d,x as c,o as r,c as A,q as i,j as l,D as t,d as E,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"直接映射 Cache","description":"","frontmatter":{"title":"直接映射 Cache","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/direct-mapped-cache.md","filePath":"cs/direct-mapped-cache.md","lastUpdated":1791063341000}'),p={name:"cs/direct-mapped-cache.md"};function B(D,a,h,C,m,R){const n=c("Mermaid");return r(),A("div",null,[a[2]||(a[2]=i('<h1 id="直接映射-cache" tabindex="-1">直接映射 Cache <a class="header-anchor" href="#直接映射-cache" aria-label="Permalink to &quot;直接映射 Cache&quot;">​</a></h1><div class="epigraph"><p>用地址的中间几位选一行、高位当标签，SRAM 才能在一拍里回答「这块在不在」。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/locality-principle">上一课</a>钉死了时间与空间局部性，并指出平均访存时间依赖命中。<a href="/cs/locality-principle">SRAM 与 DRAM 阵列</a>给出两种阵列。本课不重讲局部性定义。缺口是：还没有一种硬件结构，能按地址在 SRAM 里查找最近用过的块。本课只交出直接映射：每个主存块只能放进唯一一行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>局部性说「该留下最近的块」，没说块怎么编号、怎么判定命中。若每条 load 都把地址与全部 SRAM 内容比较，比较器会比 DRAM 还慢。缺口不是再买更大的 DRAM，而是<strong>把地址切成标签、索引、块内偏移</strong>，用索引做阵列寻址，只用标签做相等比较。</p><p>空间局部性要求块大于一个字：一次缺失把邻近字一并取来。本课取块大小为 \\(2^b\\) 字节，不讨论写策略。</p><p><span class="marginnote">直接映射是相联度 1：冲突时只能踢掉那一行上的唯一块。组相联是下一课。</span></p><p><span class="marginnote">直觉类比：索引像停车场的车位号——地址直接算出「只能停几号位」；标签像车牌，访问时只核对「这个位上停的是不是我要的那辆车」。好处是只查一个车位、一拍出结果；代价是两辆常一起用的车若被分到同一车位号，就会不停互相顶走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 cache 有 \\(2^n\\) 行，每行一块。地址低 \\(b\\) 位是块内偏移，接着 \\(n\\) 位是索引，其余高位是标签。访问时读出该行的标签与有效位，与地址标签比较：相等则命中，用偏移选字；否则缺失，从 DRAM 填入该行，改标签。</p>',10)),(r(),l(s,null,{default:t(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20OFF%5B%22%E5%81%8F%E7%A7%BB%22%5D%0A%20%20ADDR%20--%3E%20IDX%5B%22%E7%B4%A2%E5%BC%95%20%E2%86%92%20%E5%94%AF%E4%B8%80%E8%A1%8C%22%5D%0A%20%20ADDR%20--%3E%20TAG%5B%22%E6%A0%87%E7%AD%BE%E6%AF%94%E8%BE%83%22%5D%0A%20%20IDX%20--%3E%20ROW%5B%22SRAM%20%E8%A1%8C%22%5D%0A%20%20TAG%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E6%88%96%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20ROW%20--%3E%20HIT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"一行还要有效位。本课暂不设脏位——那是写回课才需要的。取指与数据可以各用一个直接映射阵列，对应上一课结构冒险里的分体存储。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"命中路径是 SRAM 读加比较，延迟按 cache 命中时间进 CPI。缺失则停顿流水线，付 DRAM 块传输代价。两个经常一起用、但索引相同、标签不同的块会反复互踢：这是冲突，不是容量不够。本课只承认会发生；分类在缺失分类课。",-1)),a[6]||(a[6]=e("p",null,"直接映射的硬件最简单：无需在一行里选路，也无需替换策略——能放的位置只有一个。这是它作为第一课 cache 的理由。",-1)),(r(),l(s,null,{default:t(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20B0%5B%22%E5%9D%97%200%EF%BC%88%E6%95%B0%E7%BB%84%20a%EF%BC%89%22%5D%20--%3E%7C%22%E7%B4%A2%E5%BC%95%3D0%22%7C%20R0%5B%22%E8%A1%8C%200%22%5D%0A%20%20B4%5B%22%E5%9D%97%204%EF%BC%88%E6%95%B0%E7%BB%84%20b%EF%BC%89%22%5D%20--%3E%7C%22%E7%B4%A2%E5%BC%95%3D0%EF%BC%884%20mod%204%EF%BC%89%22%7C%20R0%0A%20%20B1%5B%22%E5%9D%97%201%22%5D%20--%3E%7C%22%E7%B4%A2%E5%BC%95%3D1%22%7C%20R1%5B%22%E8%A1%8C%201%22%5D%0A%20%20R0%20--%3E%20T1%5B%22%E8%AE%BF%E9%97%AE%20a%EF%BC%9A%E8%B8%A2%E6%8E%89%20b%22%5D%20--%3E%20T2%5B%22%E8%AE%BF%E9%97%AE%20b%EF%BC%9A%E8%B8%A2%E6%8E%89%20a%22%5D%20--%3E%20T1%0A%20%20R1%20--%3E%20OK%5B%22%E5%9D%97%201%20%E5%AE%89%E7%84%B6%E5%B8%B8%E9%A9%BB%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>这张图回答「冲突缺失为什么在 cache 远没装满时也会发生」：4 行 cache、块大小 16 B 时，块 0 与块 4 的索引同为 \\(0 \\bmod 4 = 0\\)，只能轮流占行 0——哪怕其余 3 行全空着。数字实例：循环里交替读一次 <code>a[i]</code>、读一次 <code>b[i]</code>，若二者恰好隔了 4 个块，就是每次访问都缺失的「乒乓」。</p><p><span class="marginnote">常见误区：初学者看到程序慢、缺失多，第一反应是「cache 太小」。实际上一类缺失叫冲突缺失：把其中一个数组首地址挪开几十字节（padding），或改成组相联，性能立刻恢复，容量一个字节都没加。判断依据是「互踢的两块是否索引相同」，不是看总占用有没有超过容量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多路、不引入 LRU，不处理写命中是写 SRAM 还是写 DRAM。也不把 cache 做成程序员可见的 ISA 对象：地址仍是字节地址，命中对软件透明。一致性尚未进场。</p><p>后课默认：谈到 cache，先有标签、索引、偏移和有效位。直接映射是相联度 1 的特例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>地址切成标签 / 索引 / 偏移；索引选定唯一行。</li><li>命中比较标签；缺失从 DRAM 填该行。</li><li>组相联、写策略、三类缺失是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V cache 章。</li></ul>',7))])}const b=d(p,[["render",B]]);export{f as __pageData,b as default};
